import sys, math

data = sys.stdin.read().strip().split()
if len(data) < 3:
    sys.exit()

try:
    a, b, c = map(float, data[:3])
except ValueError:
    sys.exit()

if a <= 0 or b <= 0 or c <= 0 or (a + b <= c) or (a + c <= b) or (b + c <= a):
    print("Invalid triangle")
else:
    s = (a + b + c) / 2.0
    area = math.sqrt(max(0.0, s * (s - a) * (s - b) * (s - c)))
    print(f"{area:.2f}")

