def has_nested_pair(s: str) -> bool:
    for i, ch in enumerate(s):
        if ch == ')':
            continue
        depth = 0
        max_depth = 0
        for j in range(i, len(s)):
            if s[j] == '(':
                depth += 1
                if depth > max_depth:
                    max_depth = depth
            elif s[j] == ')':
                depth -= 1
                if depth == 0:
                    if max_depth >= 2:
                        return True
                    break
    return False
