import sys

s = sys.stdin.read()
parts = s.split(' ')
mapped = []
for p in parts:
    if p == '':
        mapped.append('')
    elif p == 'o':
        mapped.append('4')
    elif p == 'o|':
        mapped.append('2')
    elif p == '.|':
        mapped.append('1')
    else:
        mapped.append(p)

print(' '.join(mapped))
